-- Demo_site: Website + Digital Growth foundation
create table if not exists public.growth_websites (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, name text not null, slug text, business_type text not null default 'Business', status text not null default 'draft' check (status in ('draft','published')), payload jsonb not null default '{}'::jsonb, published_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.seo_audits (id uuid primary key default gen_random_uuid(), tenant_id uuid references public.tenants(id) on delete cascade, url text not null, score integer, status text not null default 'completed', issues jsonb not null default '[]'::jsonb, recommendations jsonb not null default '[]'::jsonb, raw_signals jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.growth_clients (id uuid primary key default gen_random_uuid(), tenant_id uuid references public.tenants(id) on delete cascade, business_name text not null, contact text, website text, industry text, location text, score integer, status text not null default 'New' check (status in ('New','Audited','Contacted','Interested','Proposal','Won','Client')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.growth_reports (id uuid primary key default gen_random_uuid(), tenant_id uuid references public.tenants(id) on delete cascade, client_id uuid references public.growth_clients(id) on delete set null, title text not null default 'Digital Growth Report', status text not null default 'draft' check (status in ('draft','ready','sent')), payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.competitors (id uuid primary key default gen_random_uuid(), tenant_id uuid references public.tenants(id) on delete cascade, business_name text not null, website text, industry text, location text, source text, verification_status text not null default 'unverified', findings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists growth_websites_tenant_idx on public.growth_websites(tenant_id,updated_at desc);
create index if not exists seo_audits_tenant_idx on public.seo_audits(tenant_id,created_at desc);
create index if not exists growth_clients_tenant_idx on public.growth_clients(tenant_id,created_at desc);
create index if not exists growth_reports_tenant_idx on public.growth_reports(tenant_id,created_at desc);
create index if not exists competitors_tenant_idx on public.competitors(tenant_id,created_at desc);
alter table public.growth_websites enable row level security;
alter table public.seo_audits enable row level security;
alter table public.growth_clients enable row level security;
alter table public.growth_reports enable row level security;
alter table public.competitors enable row level security;
drop policy if exists growth_websites_member on public.growth_websites;
drop policy if exists seo_audits_member on public.seo_audits;
drop policy if exists growth_clients_member on public.growth_clients;
drop policy if exists growth_reports_member on public.growth_reports;
drop policy if exists competitors_member on public.competitors;
create policy growth_websites_member on public.growth_websites for all to authenticated using (exists(select 1 from public.tenant_members tm where tm.tenant_id=growth_websites.tenant_id and tm.user_id=(select auth.uid()))) with check (exists(select 1 from public.tenant_members tm where tm.tenant_id=growth_websites.tenant_id and tm.user_id=(select auth.uid())));
create policy seo_audits_member on public.seo_audits for all to authenticated using (tenant_id is null or exists(select 1 from public.tenant_members tm where tm.tenant_id=seo_audits.tenant_id and tm.user_id=(select auth.uid()))) with check (tenant_id is null or exists(select 1 from public.tenant_members tm where tm.tenant_id=seo_audits.tenant_id and tm.user_id=(select auth.uid())));
create policy growth_clients_member on public.growth_clients for all to authenticated using (tenant_id is null or exists(select 1 from public.tenant_members tm where tm.tenant_id=growth_clients.tenant_id and tm.user_id=(select auth.uid()))) with check (tenant_id is null or exists(select 1 from public.tenant_members tm where tm.tenant_id=growth_clients.tenant_id and tm.user_id=(select auth.uid())));
create policy growth_reports_member on public.growth_reports for all to authenticated using (tenant_id is null or exists(select 1 from public.tenant_members tm where tm.tenant_id=growth_reports.tenant_id and tm.user_id=(select auth.uid()))) with check (tenant_id is null or exists(select 1 from public.tenant_members tm where tm.tenant_id=growth_reports.tenant_id and tm.user_id=(select auth.uid())));
create policy competitors_member on public.competitors for all to authenticated using (tenant_id is null or exists(select 1 from public.tenant_members tm where tm.tenant_id=competitors.tenant_id and tm.user_id=(select auth.uid()))) with check (tenant_id is null or exists(select 1 from public.tenant_members tm where tm.tenant_id=competitors.tenant_id and tm.user_id=(select auth.uid())));
